<template>
  <Layout>
    <view class="page">
      <!-- 内容区域 -->
      <view class="content">
        <!-- 统计卡片 -->
        <AssetStatsCard
          v-if="sortedAndFilteredAssets"
          :count="sortedAndFilteredAssets.length"
          :total-count="assets.length"
          :left-value="totalAmount"
          :right-value="dailyAvg"
          @filter-change="onFilterChange"
        />

        <!-- 操作栏 -->
        <AssetToolbar
          v-if="viewMode"
          v-model:viewMode="viewMode"
          @sort-change="onSortChange"
          @view-change="onViewChange"
        />

        <!-- 资产列表 -->
        <view class="scrollable-container">
          <AssetList
            v-if="assets"
            :assets="sortedAndFilteredAssets"
            :view-mode="viewMode"
            :filter-status="filterStatus"
            :filter-category="filterCategory"
          />
        </view>
      </view>
    </view>
  </Layout>
</template>

<script setup>
import { onShow } from '@dcloudio/uni-app'; 
import { ref, computed } from 'vue'
import { fetchAssetList } from '@/api/asset'; 
import Layout from '@/components/layout/Layout.vue'
import AssetStatsCard from '@/components/asset/AssetStatsCard.vue'
import AssetToolbar from '@/components/asset/AssetToolbar.vue'
import AssetList from '@/components/asset/AssetList.vue'
import { calculateDaysToNow } from '@/utils/dateUtils'


const assets = ref([]);
const loadAssets = async () => {
  try {
    const response = await fetchAssetList();
    // 打印后端返回的完整数据结构
    console.log('后端返回的完整数据:', response);
    assets.value = response.data.list;
  } catch (error) {
    console.error('获取资产失败:', error);
  }
};

onShow(() => {
  loadAssets(); // 在组件挂载时调用此函数加载资产列表数据
});

// 计算后的资产列表
const computedAssets = computed(() => {
  return assets.value.map(asset => ({
    ...asset,
    days: calculateDaysToNow(asset.purchaseDate)
  }))
})

// 筛选条件
const filterStatus = ref('全部')
const filterCategory = ref('全部')

// 视图模式
const viewMode = ref('list')

// 排序
const sortType = ref('name') // 'name', 'amount', 'days'

// 排序后的资产列表
const sortedAndFilteredAssets = computed(() => {
  return computedAssets.value
    .filter(asset => {
      const statusMatch = filterStatus.value === '全部' || asset.status === filterStatus.value
      const categoryMatch = filterCategory.value === '全部' || asset.category === filterCategory.value
      return statusMatch && categoryMatch
    })
    .sort((a, b) => {
      if (sortType.value === 'name') {
        return a.name.localeCompare(b.name)
      } else if (sortType.value === 'amount') {
        return parseFloat(b.price) - parseFloat(a.price)
      } else if (sortType.value === 'days') {
        return b.days - a.days
      }
      return 0
    })
})

// 计算总金额
const totalAmount = computed(() => {
  return computedAssets.value.reduce((sum, item) => {
    // 修复：将amount改为price，与后端字段一致，并转换为数字
    return sum + parseFloat(item.price)
  }, 0)
})
// 计算日均
const dailyAvg = computed(() => {
  return computedAssets.value
    .reduce((sum, item) => {
      // 修复：将amount改为price，与后端字段一致，并转换为数字
      const itemDailyAvg = item.days > 0 ? (parseFloat(item.price) / item.days) : 0;
      return sum + itemDailyAvg;
    }, 0)
    .toFixed(2);
})

// 筛选条件变化
const onFilterChange = ({ status, category }) => {
  filterStatus.value = status
  filterCategory.value = category
}

// 排序变化
const onSortChange = (type) => {
  sortType.value = type
}

// 视图模式变化
const onViewChange = (mode) => {
  viewMode.value = mode
}
</script>

<style scoped>
.page {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.content {
  height: 100%;
}

.scrollable-container {
  overflow-y: auto; /* 只允许垂直滚动 */
  -webkit-overflow-scrolling: touch; /* iOS 滚动优化 */
  box-sizing: border-box;
  height: 480px;
}
</style>